Set Variable [ $r ; Value: Let([
contacts = MBS( "CNContactStore.ContactsMatchingName"; "Christian Schmitz" );
contactID = GetValue(contacts; 1);
json = MBS( "CNContact.JSON"; contactID; 1 )
];json) ]

Set Variable [ $r ; Value: While( 
[ 
	names = ""; 
	// query list of contact IDs
	list = MBS( "CNContactStore.Contacts"; 1 ); 
	count = ValueCount(list); 
	index = 1
] ; 
	index ≤ count ; 
[ 
	id = GetValue(list; index); 
	// query name for each ID
	name = MBS( "CNContact.Name"; id); 
	names = names & name & ¶; 
	index = index + 1 
] ; 
// return all the names
names ) ]

Set Variable [ $r ; Value: MBS( "CNContact.SetValue"; "BD2307E5-92F6-4A8F-946D-C4804615C18B:ABPerson"; "emailAddresses"; "[]") &
// first set email list to empty JSON array and save
MBS( "CNContactStore.UpdateContact";  "BD2307E5-92F6-4A8F-946D-C4804615C18B:ABPerson" ) ]

Set Variable [ $r ; Value: MBS( "CNContact.Value"; "BD2307E5-92F6-4A8F-946D-C4804615C18B:ABPerson"; "emailAddresses"; "[{ \"label\" : \"_$!<Home>!$_\", \"value\" : \"home@test.de\" }, { \"label\" : \"My Label\", \"value\" : \"private@test.de\" } ]") &
// and save
MBS( "CNContactStore.UpdateContact";  "BD2307E5-92F6-4A8F-946D-C4804615C18B:ABPerson" ) ]

Set Variable [ $r ; Value: Let ( [
  path = MBS( "Files.ApplicationPathWithBundleIdentifier"; "com.apple.ical" );
  r = MBS( "Files.Launch"; path)  
]; r ) ]

Set Variable [ $r ; Value: Let ( [
jsonFormatted = MBS("JSON.Format"; Self);
jsonFormatFailed = MBS("IsError");
jsonText = If(jsonFormatFailed; Self; jsonFormatted);
result = MBS("JSON.Colorize"; jsonText)
]; result )

// put this calculation into a field, so the field gets formated and colorized whenever the field is changed and the record gets commited. ]

Set Variable [ $r ; Value: While( 
[ 
	names = ""; 
	// query list of visible files on desktop
	folder = MBS("Folders.UserDesktop");
	list = MBS( "Files.List"; folder; 1+4 ); 
	count = ValueCount(list); 
	index = 1
] ; 
	index ≤ count ; 
[ 
	filename = GetValue(list; index); 
	filepath = MBS("Path.AddPathComponent"; folder; filename);
	// query size for each file
	size = MBS( "Files.FileSize"; filepath); 
	names = names & filename & " -> " & size & ¶; 
	index = index + 1 
] ; 
// return all the names
names ) ]

