Set Variable [ $r ; Value: MBS( "JSON.SortWithEvaluate"; 
 MBS( "Files.ListAsJSON"; 
  MBS("Folders.UserDesktop"); 
 "Size" ); 
"JSONGetElement ( leftJSON; \"Name\") < JSONGetElement ( rightJSON; \"Name\")" ) ]

