"JSONGetElement ( leftJSON; \"Size\") > JSONGetElement ( rightJSON; \"Size\")" ) ]

Set Variable [ $r ; Value: Let ( [
	path = MBS("Folders.UserDesktop");
	list = MBS( "Files.ListAsJSON"; path; "CreationTimeStamp¶ModificationTimeStamp" );
	sort = MBS( "JSON.SortWithEvaluate"; list; "GetAsTimeStamp(JSONGetElement ( leftJSON; \"ModificationTimeStamp\")) < GetAsTimeStamp(JSONGetElement ( rightJSON; \"ModificationTimeStamp\"))" )
];sort) ]

Set Variable [ $r ; Value: Let([
	WindowCenterX = MBS( "Window.GetLeft"; 0 ) + MBS( "Window.GetWidth"; 0 );
	WindowCenterY = MBS( "Window.GetTop"; 0 ) + MBS( "Window.GetHeight"; 0 );
	$ScreenIndex = -1;

	r = While ( 
	[ 
		c = MBS( "Screen.Count" ); 
		i = 0 
	] ; 
	i < c ; 
	[ 
		l = MBS( "Screen.Left"; i );
		t = MBS( "Screen.Top"; i );
		w = MBS( "Screen.Width"; i );
		h = MBS( "Screen.Height"; i );
		$ScreenIndex = If( 
			(l ≤ WindowCenterX) AND 
			(t ≤ WindowCenterY) AND 
			(WindowCenterX ≤ l + w) AND 
			(WindowCenterY ≤ t + h) ; i; $ScreenIndex ); 
		i = i + 1 ] ; 0 )

]; $ScreenIndex) ]

